/** Original, playable phrase studies. Offsets are semitones from the song's
 * tonic, not instructions to transpose the tune at every chord change.
 * These are teaching adaptations, not transcriptions of reference recordings.
 * Each entry spells out its own rhythm, contour, holds and response. */
interface Study {
  name: string;
  onsets: number[];
  tones: number[];
  response: number[];
  durations: number[];
  /** Explicit phrase space beyond the last attack, when composition needs it. */
  cycleLength?: number;
}
const S = (name: string, onsets: number[], tones: number[], response: number[], durations: number[]): Study =>
  ({ name, onsets, tones, response, durations });

