function isPlaceholder(cell: AuthoredCell): boolean {
  // A stop, pickup, pedal or exposed long tone can share attack points with
  // the old scaffold. Replace only that original statement scaffold.
  if (!/\bstatement$/i.test(cell.name)) return false;
  const positions = JSON.stringify(cell.onsets);
  return positions === '[0,0.75,1.5]' || positions === '[2,2.75,3.5]' || positions === '[0]';
}

function pitchedLead(cell: AuthoredCell): boolean {
  return /^(lead|melody|voice|counterline)$/.test(cell.role) && !!cell.instruments?.length
    && cell.instruments.every(id => {
      const instrument = INSTRUMENTS_BY_ID[id];
      return instrument && instrument.voicing !== 'unpitched' && !instrument.kit && !instrument.drum;
    });
}

/** Replace known placeholder cells, retaining their IDs and instrument/role
 * assignments. Other rhythm lessons keep every written attack and rest; only
 * their previously unspecified pitch is supplied by the local melodic study.
 * Existing pitched studies and contact techniques are never overwritten. */
export function authorMelodicStudies(pack: GenrePackInput): GenrePackInput {
  const studies = STUDIES[pack.id];
  if (!studies) return pack;
  return { ...pack, styles: pack.styles.map(style => {
    const study = studies[style.id];
    if (!study) return style;
    if (!study.onsets.length || [study.tones, study.response, study.durations].some(values => values.length !== study.onsets.length)) {
      throw new Error(`Misaligned melodic study: ${pack.id}/${style.id}`);
    }
    const [n, d] = style.meter.split('/').map(Number);
    const beats = n * 4 / d;
    // Ringing over a bar line does not add an empty bar to the rhythmic cycle.
    // Short phrases can repeat after one bar; longer spaces are written above.
    const cycleLength = study.cycleLength ?? Math.floor(Math.max(...study.onsets) / beats) + 1;
    const players = [...new Set(style.cells.filter(pitchedLead).flatMap(cell => cell.instruments!))];
    const returns = new Map<string, AuthoredCell>();
    const cells = style.cells.map(cell => {
      if (!pitchedLead(cell) || cell.pitches?.some(Boolean)) return cell;
      const instrumentId = cell.instruments![0];
      const instrument = INSTRUMENTS_BY_ID[instrumentId];
      const register = instrument.acousticProfile?.centre ?? FAMILY_DEFAULTS[instrument.family]?.centre;
      if (register === undefined) throw new Error(`Missing melodic register for ${instrumentId}`);
      const response = players.indexOf(instrumentId) > 0;
      const tones = response ? study.response : study.tones;
      const placeholder = !cell.phraseEnd && cell.timingLock !== 'ensemble' && !cell.notations?.some(Boolean) && isPlaceholder(cell);
      const onsets = placeholder ? study.onsets : cell.onsets;
      const pitchAt = (values: number[], i: number) => ({ semitoneOffset: values[i % values.length],
        register, voicing: 'single' as const, reference: 'tonic' as const });
      // Agogic stress follows the actual held tones and melodic high point.
      // Existing written accents/velocities remain authoritative on rhythm
      // lessons; no shared meter accent is inserted over them.
      const longest = Math.max(...study.durations);
      const expressionFor = (values: number[], count: number) => {
        const peak = Math.max(...values), bottom = Math.min(...values);
        return Array.from({ length: count }, (_, i) => .52
          + .17 * (values[i % values.length] - bottom) / Math.max(1, peak - bottom)
          + .18 * study.durations[i % study.durations.length] / longest);
      };
      const expression = expressionFor(tones, onsets.length);
      const authored: AuthoredCell = { ...cell,
        ...(placeholder ? { onsets: [...onsets], durations: [...study.durations], cycleLength,
          microtiming: undefined, probabilities: undefined, articulations: undefined, notations: undefined, hits: undefined,
          accents: expression, velocities: expression } : {}),
        pitches: onsets.map((_, i) => pitchAt(tones, cell.phraseEnd ? Math.max(0, tones.length - onsets.length) + i : i)),
        description: `${study.name}. Keep the written holds and spaces, and let the phrase travel through the chord changes. Original ${style.name} teaching study; not a recording transcription.`,
      };
      if (!cell.phraseEnd && !returns.has(instrumentId)) {
        const alternate = response ? study.tones : study.response;
        const returnExpression = expressionFor(alternate, study.onsets.length).map(value => value * .92);
        returns.set(instrumentId, { ...authored,
          name: `${cell.name} melodic return`, shortName: `${instrument.name.split(' ').slice(0, 2).join(' ')} return`,
          onsets: [...study.onsets], durations: [...study.durations], cycleLength,
          pitches: study.onsets.map((_, i) => pitchAt(alternate, i)),
          accents: returnExpression, velocities: returnExpression,
          microtiming: undefined, probabilities: undefined, articulations: undefined, notations: undefined, hits: undefined,
          arrangementVariation: true,
          description: `Answer the ${study.name.toLowerCase()} with its second written contour. Keep the phrase space and return to the theme. Original teaching adaptation.`,
        });
      }
      return authored;
    });
    // The newly continuous drone must sit inside the ambient field. Its old
    // short guide attacks had a much lower sounding occupancy at this gain.
    const mix = pack.id === 'ambient' && style.id === 'drone'
      ? { ...style.mix, roles: { ...style.mix.roles, lead: { ...style.mix.roles?.lead,
        gainDb: (style.mix.roles?.lead?.gainDb ?? 0) - 4.5, foregroundGainDb: .5 } } }
      : style.mix;
    return { ...style, mix, cells: [...cells, ...returns.values()] };
  }) };
}
